#!/usr/bin/env bash
# nessus2report.sh
# One or two .nessus files in (External and/or Internal), one completed EIVA .docx report out.
# The Abacode report template is built into this script.
#
# Usage (every flag is optional; anything missing is prompted for):
#   ./nessus2report.sh -e external.nessus -i internal.nessus -c "Acme Health Inc" -a ACME -r assessment
#
#   -e  external .nessus file (fills the EVA sections)
#   -i  internal .nessus file (fills the IVA sections)
#   -c  customer full name
#   -a  customer abbreviation (used in the header and body)
#   -r  assessment | scan   (scan = the trimmed Executive Summary scan report with quarter dates)
#   -d  cover date text (default: today's date)
#   -o  output .docx path
#   -n  leave out Informational findings without asking

set -euo pipefail

EXT="" ; INT="" ; FULL="" ; ABBR="" ; RTYPE="" ; DATE_TXT="" ; OUT="" ; NOINFO=0

while getopts "e:i:c:a:r:d:o:nh" opt; do
  case $opt in
    e) EXT="$OPTARG" ;; i) INT="$OPTARG" ;; c) FULL="$OPTARG" ;; a) ABBR="$OPTARG" ;;
    r) RTYPE="$OPTARG" ;; d) DATE_TXT="$OPTARG" ;; o) OUT="$OPTARG" ;; n) NOINFO=1 ;;
    h) sed -n '2,17p' "$0"; exit 0 ;;
    *) exit 1 ;;
  esac
done

clean_path() { local p="$1"; p="${p%\"}"; p="${p#\"}"; p="${p%\'}"; p="${p#\'}"; p="${p%% }"; echo "$p"; }

# Dependencies: lxml (ships with Kali). This script never installs anything.
if ! python3 -c "import lxml" 2>/dev/null; then
  echo "[!] python3-lxml is missing. Install it with: sudo apt install python3-lxml"; exit 1
fi
if [[ -z "$EXT" && -z "$INT" ]]; then
  read -rp "External .nessus file (press Enter to skip): " EXT
  read -rp "Internal .nessus file (press Enter to skip): " INT
fi
EXT="$(clean_path "$EXT")"; INT="$(clean_path "$INT")"
[[ -z "$EXT" && -z "$INT" ]] && { echo "[!] At least one .nessus file is required."; exit 1; }
[[ -n "$EXT" && ! -f "$EXT" ]] && { echo "[!] File not found: $EXT"; exit 1; }
[[ -n "$INT" && ! -f "$INT" ]] && { echo "[!] File not found: $INT"; exit 1; }

[[ -z "$FULL" ]] && read -rp "Customer full name: " FULL
[[ -z "$ABBR" ]] && read -rp "Customer abbreviation: " ABBR

while [[ ! "${RTYPE,,}" =~ ^(assessment|scan|a|s)$ ]]; do
  read -rp "Report type: Assessment or Scan? [a/s]: " RTYPE
done
case "${RTYPE,,}" in s|scan) RTYPE="scan" ;; *) RTYPE="assessment" ;; esac

if [[ "$NOINFO" != 1 ]]; then
  read -rp "Skip Informational findings? [y/N]: " ans
  [[ "${ans,,}" =~ ^y ]] && NOINFO=1
fi

WORK="$(mktemp -d)"; trap 'rm -rf "$WORK"' EXIT
TEMPLATE="$WORK/template.docx"
if [[ "$RTYPE" == "scan" ]]; then
  sed -n '/^__SCAN_TEMPLATE_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d > "$TEMPLATE"
else
  sed -n '/^__TEMPLATE_BELOW__$/,/^__SCAN_TEMPLATE_BELOW__$/p' "$0" | sed '1d;$d' | base64 -d > "$TEMPLATE"
fi

export EXT INT FULL ABBR RTYPE DATE_TXT TEMPLATE OUT NOINFO WORK

python3 - <<'PYEOF'
import os, re, sys, zipfile, copy, datetime, subprocess, shutil
from collections import defaultdict
from lxml import etree

E = os.environ
FULL, ABBR, RTYPE, TEMPLATE, WORK = E["FULL"].strip(), E["ABBR"].strip(), E["RTYPE"], E["TEMPLATE"], E["WORK"]
NOINFO = E["NOINFO"] == "1"
INPUTS = {"EVA": E["EXT"], "IVA": E["INT"]}
INPUTS = {k: v for k, v in INPUTS.items() if v}

SEVS = ["Critical", "High", "Medium", "Low", "Informational"]
SEV_COLOR = {"Critical": "C00000", "High": "FF0000", "Medium": "ED7D31",
             "Low": "4472C4", "Informational": "808080"}
# Custom criticality overrides carried over from Parse-Nessus.ps1
# SSL/TLS findings (matches "SSL", "TLS", "SSLv3", "TLSv1.0" etc. but not "OpenSSL" version/patch findings)
TLS_RE = re.compile(r"(?<![A-Za-z])(SSL|TLS)")
OVERRIDES = {"Server Message Block (SMB) Protocol Version 1 Enabled (uncredentialed check)": "High"}

# ================================================================ parse .nessus
def parse_time(tags, key):
    ts = tags.get(key + "_TIMESTAMP")
    if ts and ts.isdigit():
        return datetime.datetime.fromtimestamp(int(ts))
    v = tags.get(key)
    if v:
        try: return datetime.datetime.strptime(v.strip(), "%a %b %d %H:%M:%S %Y")
        except ValueError: pass
    return None

def parse_nessus(path, prefix):
    tree = etree.parse(path, etree.XMLParser(huge_tree=True, recover=True))
    findings, starts, ends = {}, [], []
    for rh in tree.iter("ReportHost"):
        tags = {t.get("name"): (t.text or "") for t in rh.iter("tag")}
        ip = tags.get("host-ip") or rh.get("name")
        fqdn = tags.get("host-fqdn") or (rh.get("name") if rh.get("name") != ip else "")
        host = f"{ip} ({fqdn})" if fqdn and fqdn != ip else ip
        for k, lst in (("HOST_START", starts), ("HOST_END", ends)):
            t = parse_time(tags, k)
            if t: lst.append(t)
        for ri in rh.iter("ReportItem"):
            name = ri.get("pluginName", "").strip()
            rf = (ri.findtext("risk_factor") or "None").strip()
            sev = OVERRIDES.get(name, rf)
            sev = "Informational" if sev in ("None", "Info", "") else sev
            if sev not in SEVS: sev = "Informational"
            if NOINFO and sev == "Informational": continue
            pid = ri.get("pluginID")
            f = findings.get(pid)
            if f is None:
                f = findings[pid] = {"name": name, "sev": sev,
                                     "desc": (ri.findtext("description") or "").strip(),
                                     "sol": (ri.findtext("solution") or "").strip(),
                                     "hosts": defaultdict(set)}
            elif SEVS.index(sev) < SEVS.index(f["sev"]):
                f["sev"] = sev
            port, proto = ri.get("port", "0"), ri.get("protocol", "")
            if port != "0": f["hosts"][host].add(f"{port}/{proto}")
            else: f["hosts"][host]
    # Roll every SSL/TLS finding into a single "Multiple SSL/TLS Issues" finding
    tls = [k for k, f in findings.items() if TLS_RE.search(f["name"])]
    if tls:
        sev = min((findings[k]["sev"] for k in tls), key=SEVS.index)
        for k in tls: del findings[k]
        findings["__tls__"] = {
            "name": "Multiple SSL/TLS Issues", "sev": sev,
            "desc": f"Several Hosts have {sev.lower()} severity vulnerabilities concerning SSL/TLS encryption "
                    "configuration. Review the accompanying reports for a detailed list of vulnerabilities "
                    "and their affected hosts.",
            "sol": "Review SSL configuration, tracking, and testing process, and implement best practices around "
                   "internet-facing sites and then internal assets. Many hosts are affected by more than one "
                   "vulnerability. Consider using a dependable Certificate Authority (CA) that is subject to "
                   "rigorous third-party auditing to maintain their position in major operating system and root "
                   "certificate programs.",
            "assets_text": "Multiple assets on the target network are affected by these vulnerabilities. "
                           "Please see accompanying files for more information.",
            "hosts": {}}
    ordered = sorted(findings.values(), key=lambda f: (SEVS.index(f["sev"]), f["name"].lower()))
    for i, f in enumerate(ordered, 1):
        f["id"] = f"{prefix}-{i:02d}"
    targets = ""
    for p in tree.iter("preference"):
        if p.findtext("name") == "TARGET":
            targets = p.findtext("value") or ""
    return {"findings": ordered,
            "counts": {s: sum(1 for f in ordered if f["sev"] == s) for s in SEVS},
            "targets": [t.strip() for t in re.split(r"[,\n]", targets) if t.strip()],
            "start": min(starts) if starts else None, "end": max(ends) if ends else None}

scans = {k: parse_nessus(v, k) for k, v in INPUTS.items()}

today = datetime.date.today()
def quarter_of(d): return f"Q{(d.month - 1)//3 + 1} {d.year}"
scan_ref = max((s["end"] for s in scans.values() if s["end"]), default=datetime.datetime.now())
if RTYPE == "scan":
    cover_date = E["DATE_TXT"] or quarter_of(scan_ref)
else:
    cover_date = E["DATE_TXT"] or today.strftime("%B %-d, %Y")

def scope_dates(sc):
    ref = sc["end"] or datetime.datetime.now()
    if RTYPE == "scan":
        return f"Q{(ref.month - 1)//3 + 1} {ref.year}"
    s0 = sc["start"] or ref
    if s0.date() == ref.date(): return f"{ref.day} {ref:%B %Y}"
    if (s0.year, s0.month) == (ref.year, ref.month): return f"{s0.day} \u2013 {ref.day} {ref:%B %Y}"
    if s0.year == ref.year: return f"{s0.day} {s0:%B} \u2013 {ref.day} {ref:%B %Y}"
    return f"{s0.day} {s0:%B %Y} \u2013 {ref.day} {ref:%B %Y}"

# ================================================================ docx helpers
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
w = lambda t: f"{{{W}}}{t}"
XML_SPACE = "{http://www.w3.org/XML/1998/namespace}space"

zin = zipfile.ZipFile(TEMPLATE)
files = {n: zin.read(n) for n in zin.namelist()}
doc = etree.fromstring(files["word/document.xml"])
body = doc.find(w("body"))

def text(el): return "".join(t.text or "" for t in el.iter(w("t")))
def own_ts(p): return [t for t in p.iter(w("t")) if next(t.iterancestors(w("p"))) is p]

def unhighlight(run):
    for h in run.iter(w("highlight")): h.getparent().remove(h)

def replace_in(root, old, new):
    for p in root.iter(w("p")):
        while True:
            ts = own_ts(p)
            full = "".join(t.text or "" for t in ts)
            idx = full.find(old)
            if idx < 0: break
            end, pos, spans = idx + len(old), 0, []
            for t in ts:
                s = t.text or ""; a, b = pos, pos + len(s); pos = b
                if b > idx and a < end:
                    spans.append((t, max(idx, a) - a, min(end, b) - a))
            host = max(spans, key=lambda x: x[2] - x[1])[0]
            for t, lo, hi in spans:
                s = t.text or ""
                t.text = s[:lo] + (new if t is host else "") + s[hi:]
                t.set(XML_SPACE, "preserve")
            unhighlight(host.getparent())

def set_para_text(p, value):
    runs = [r for r in p.iter(w("r")) if r.find(w("t")) is not None]
    for r in runs[1:]: r.getparent().remove(r)
    t = runs[0].find(w("t")); t.text = value; t.set(XML_SPACE, "preserve")
    unhighlight(runs[0])

def strip_bookmarks(el):
    for b in list(el.iter(w("bookmarkStart"), w("bookmarkEnd"))):
        b.getparent().remove(b)
    return el

def remove_all(els):
    ids = {b.get(w("id")) for e in els for b in e.iter(w("bookmarkStart"), w("bookmarkEnd"))}
    for e in els:
        if e.getparent() is not None: e.getparent().remove(e)
    for b in list(doc.iter(w("bookmarkStart"), w("bookmarkEnd"))):
        if b.get(w("id")) in ids: b.getparent().remove(b)

def style(p):
    s = p.find(f"{w('pPr')}/{w('pStyle')}")
    return s.get(w("val")) if s is not None else ""

def has_pb(p): return p.tag == w("p") and p.find(f".//{w('br')}[@{w('type')}='page']") is not None

def find_body_para(pred):
    for c in body:
        if c.tag == w("p") and pred(c): return c
    return None

def next_tbl(el):
    el = el.getnext()
    while el is not None and el.tag != w("tbl"): el = el.getnext()
    return el

def ppr(p):
    pr = p.find(w("pPr"))
    if pr is None:
        pr = etree.Element(w("pPr")); p.insert(0, pr)
    return pr

def ppr_set(p, tag, attrs=None):
    """Insert a pPr child in schema order (only the few we need)."""
    order = ["pStyle", "keepNext", "keepLines", "pageBreakBefore", "framePr", "widowControl", "numPr",
             "suppressLineNumbers", "pBdr", "shd", "tabs", "suppressAutoHyphens", "kinsoku", "wordWrap",
             "overflowPunct", "topLinePunct", "autoSpaceDE", "autoSpaceDN", "bidi", "adjustRightInd",
             "snapToGrid", "spacing", "ind", "contextualSpacing"]
    pr = ppr(p)
    old = pr.find(w(tag))
    if old is not None: pr.remove(old)
    el = etree.Element(w(tag))
    for k, v in (attrs or {}).items(): el.set(w(k), v)
    my = order.index(tag)
    for i, c in enumerate(pr):
        ln = etree.QName(c).localname
        if ln not in order or order.index(ln) > my:
            pr.insert(i, el); return el
    pr.append(el); return el

def set_shading(tc, fill):
    tcpr = tc.find(w("tcPr"))
    shd = tcpr.find(w("shd"))
    if shd is None:
        shd = etree.SubElement(tcpr, w("shd"))
    for a in list(shd.attrib): del shd.attrib[a]
    shd.set(w("val"), "clear"); shd.set(w("color"), "auto"); shd.set(w("fill"), fill)

# ================================================================ locate template blocks (before any edits)
def summary_block(pref):
    label = "Internal" if pref == "IVA" else "External"
    head = find_body_para(lambda p: re.fullmatch(rf"{label} Vulnerability (Assessment|Scan) Findings", text(p).strip()))
    t1 = next_tbl(head); t2 = next_tbl(t1)
    return {"head": head, "counts": t1, "table": t2, "remove": []}

def removal_ranges(sb_e, sb_i):
    # External: its heading up to (not including) the Internal heading
    rng, el = [], sb_e["head"]
    while el is not None and el is not sb_i["head"]:
        rng.append(el); el = el.getnext()
    sb_e["remove"] = rng
    # Internal: everything after the External table through the Internal table, plus trailing blanks
    rng, el = [], sb_e["table"].getnext()
    while el is not None:
        rng.append(el)
        if el is sb_i["table"]: break
        el = el.getnext()
    el = sb_i["table"].getnext()
    while el is not None and el.tag == w("p") and not text(el).strip() and not has_pb(el):
        rng.append(el); el = el.getnext()
    sb_i["remove"] = rng

def detail_block(pref):
    label = "INTERNAL" if pref == "IVA" else "EXTERNAL"
    head = find_body_para(lambda p: style(p) == "Heading1" and "DETAILED FINDINGS" in text(p) and label in text(p))
    if head is None: return None   # the scan report has no detailed findings pages
    items, el = [], head.getnext()
    while el is not None and not has_pb(el):
        items.append(el); el = el.getnext()
    return {"head": head, "items": items, "pb": el}

blocks = {p: (summary_block(p), detail_block(p)) for p in ("EVA", "IVA")}
removal_ranges(blocks["EVA"][0], blocks["IVA"][0])
bullet_tmpl = copy.deepcopy(find_body_para(lambda p: text(p).strip() == "Denial of Service (DoS)"))

# ================================================================ fill one section
def body_paras(raw):
    out = []
    for block in re.split(r"\n\s*\n", raw.replace("\r", "")):
        buf = []
        for line in block.split("\n"):
            line = line.strip()
            if not line: continue
            if re.match(r"^[-*]\s+", line):
                if buf: out.append(("p", " ".join(buf))); buf = []
                out.append(("b", re.sub(r"^[-*]\s+", "", line)))
            else:
                buf.append(line)
        if buf: out.append(("p", " ".join(buf)))
    return out or [("p", "N/A")]

def ipkey(h):
    ip = h.split(" ")[0]
    try: return (0, tuple(int(x) for x in ip.split(".")))
    except ValueError: return (1, ip)

def bullet(value):
    b = strip_bookmarks(copy.deepcopy(bullet_tmpl))
    set_para_text(b, value)
    ppr_set(b, "spacing", {"before": "0", "after": "0"})
    ppr_set(b, "contextualSpacing")
    return b

def fill(pref, sc):
    sb, db = blocks[pref]
    ordered, counts = sc["findings"], sc["counts"]

    for t, s in zip([t for t in sb["counts"].iter(w("t")) if t.text == "#"], SEVS):
        t.text = str(counts[s])

    tbl = sb["table"]; rows = tbl.findall(w("tr"))
    tmpl = {s: rows[i + 1] for i, s in enumerate(SEVS)}
    anchor = rows[0]
    for f in ordered:
        r = copy.deepcopy(tmpl[f["sev"]])
        set_para_text(r.findall(w("tc"))[0].find(w("p")), f"{f['id']}: {f['name']}")
        anchor.addnext(r); anchor = r
    if not ordered:
        r = copy.deepcopy(tmpl["Informational"])
        c0, c1 = r.findall(w("tc"))
        set_para_text(c0.find(w("p")), "No Notable Findings")
        set_para_text(c1.find(w("p")), "")
        set_shading(c0, "FFFFFF"); set_shading(c1, "FFFFFF")
        anchor.addnext(r)
    for s in SEVS: tbl.remove(tmpl[s])

    if db is None: return []
    it = db["items"]
    label_p, head_p, title_p, body_p = it[0], it[1], it[2], it[3]
    status_title, status_body, rec_title, assets_title = it[4], it[5], it[6], it[8]

    def clone(p, value=None):
        c = strip_bookmarks(copy.deepcopy(p))
        if value is not None: set_para_text(c, value)
        return c

    def text_block(raw):
        out = [clone(body_p, v) if k == "p" else bullet(v) for k, v in body_paras(raw)]
        for i, (k, _) in enumerate(body_paras(raw)):   # breathing room after the last bullet of a list
            nxt = body_paras(raw)[i + 1][0] if i + 1 < len(out) else None
            if k == "b" and nxt != "b": ppr_set(out[i], "spacing", {"before": "0", "after": "160"})
        return out

    new, heads = [], []
    for n, f in enumerate(ordered):
        lp = clone(label_p, f["sev"].upper())
        for c in lp.iter(w("color")): c.set(w("val"), SEV_COLOR[f["sev"]])
        ppr_set(lp, "keepNext")
        if n: ppr_set(lp, "pageBreakBefore")      # every finding after the first starts a new page
        hp = clone(head_p, f"{f['id']}: {f['name']}")
        heads.append(hp)
        new += [lp, hp, clone(title_p)] + text_block(f["desc"])
        new += [clone(status_title), clone(status_body), clone(rec_title)] + text_block(f["sol"])
        new.append(clone(assets_title))
        if f.get("assets_text"): new.append(clone(body_p, f["assets_text"]))
        for h in sorted(f["hosts"], key=ipkey):
            ports = sorted(f["hosts"][h], key=lambda x: int(x.split("/")[0]) if x.split("/")[0].isdigit() else 0)
            new.append(bullet(f"{h}: {', '.join(ports)}" if ports else h))
    if not ordered:
        new.append(clone(body_p, "No notable findings were identified."))

    remove_all(it)
    anchor = db["head"]
    for p in new:
        anchor.addnext(p); anchor = p
    return heads

finding_heads = {}
for pref, sc in scans.items():
    finding_heads[pref] = fill(pref, sc)

# ================================================================ remove unused section(s)
for pref in ("EVA", "IVA"):
    if pref in scans: continue
    sb, db = blocks[pref]
    remove_all(sb["remove"])
    if db is not None:
        remove_all([db["head"]] + db["items"] + ([db["pb"]] if db["pb"] is not None else []))

# ================================================================ scope appendix
scope_head = find_body_para(lambda p: "APPENDIX B" in text(p) and style(p) == "Heading1")
st = next_tbl(scope_head) if scope_head is not None else None
if st is not None and "#TARGET#" in text(st):
    trow = next(tr for tr in st.findall(w("tr")) if "#TARGET#" in text(tr))
    anchor = trow
    for pref in ("EVA", "IVA"):
        if pref not in scans: continue
        for tgt in scans[pref]["targets"] or ["See attached scan results"]:
            r = copy.deepcopy(trow)
            c0, c1, c2 = r.findall(w("tc"))
            set_para_text(c0.find(w("p")), tgt)
            set_para_text(c1.find(w("p")), "E" if pref == "EVA" else "I")
            set_para_text(c2.find(w("p")), scope_dates(scans[pref]))
            anchor.addnext(r); anchor = r
    st.remove(trow)
    st = None
if st is not None:
    for tr in st.findall(w("tr"))[1:]:
        tcs = tr.findall(w("tc"))
        if len(tcs) < 4: continue
        pref = {"E": "EVA", "I": "IVA"}.get(text(tcs[2]).strip())
        if pref is None: continue
        if pref not in scans:
            st.remove(tr); continue
        sc = scans[pref]
        blank = copy.deepcopy(tr)
        anchor = None
        for tgt in sc["targets"] or ["See attached scan results"]:   # one row per target
            row = tr if anchor is None else copy.deepcopy(blank)
            cells = row.findall(w("tc"))
            p0 = cells[0].find(w("p"))
            r = etree.SubElement(p0, w("r")); t = etree.SubElement(r, w("t")); t.text = tgt
            set_para_text(cells[3].find(w("p")), scope_dates(sc))
            if anchor is not None: anchor.addnext(row)
            anchor = row

# ================================================================ scan report: current quarter row of the Plus/Delta table
for tr in doc.iter(w("tr")):
    if "#DELTA ROW#" in text(tr):
        cells = tr.findall(w("tc"))
        tot = {s_: sum(sc["counts"][s_] for sc in scans.values()) for s_ in SEVS}
        vals = [quarter_of(scan_ref).replace(" ", " Scan "), tot["Critical"], tot["High"], tot["Medium"], tot["Low"],
                tot["Critical"] + tot["High"] + tot["Medium"] + tot["Low"]]
        for c, v in zip(cells, vals): set_para_text(c.find(w("p")), str(v))

# ================================================================ global placeholders
parts = {"word/document.xml": doc}
for n in files:
    if re.match(r"word/(header|footer)\d*\.xml$", n):
        parts[n] = etree.fromstring(files[n])
for root in parts.values():
    replace_in(root, "CUSTOMERFULLNAME (CUSTABBR)", f"{FULL} ({ABBR})")
    replace_in(root, "CUSTOMERFULLNAME", FULL)
    replace_in(root, "#CUSTOMER FULL NAME#", FULL)
    replace_in(root, "#FULL DATE#", cover_date)
    replace_in(root, "#CUST ABBR#", ABBR)
    if root is not doc:   # header placeholder run has no styling; give it the paragraph's white Segoe UI
        for t in root.iter(w("t")):
            if t.text == ABBR:
                r = t.getparent(); prp = r.getparent().find(f"{w('pPr')}/{w('rPr')}")
                rpr = r.find(w("rPr"))
                if prp is not None and (rpr is None or rpr.find(w("color")) is None):
                    if rpr is not None: r.remove(rpr)
                    r.insert(0, copy.deepcopy(prp))
    replace_in(root, "CUSTABBR", ABBR)
    if RTYPE == "scan":
        replace_in(root, "VULNERABILITY ASSESSMENT REPORT", "VULNERABILITY SCAN REPORT")
        replace_in(root, "Vulnerability Assessment Report", "Vulnerability Scan Report")

# ================================================================ Table of Contents
toc_sdt = next(c for c in body if c.tag == w("sdt") and "Table of Contents" in text(c))
content = toc_sdt.find(w("sdtContent"))
entries = [p for p in content.findall(w("p")) if style(p).startswith("TOC") and style(p) != "TOCHeading"]
field_begin = []   # runs holding the TOC field begin / instruction / separate, which sit before the first hyperlink
for ch in entries[0]:
    if ch.tag == w("hyperlink"): break
    if ch.tag == w("r"): field_begin.append(copy.deepcopy(ch))
toc1 = strip_bookmarks(copy.deepcopy(entries[1]))
toc3 = next((p for p in entries if style(p) == "TOC3"), None)
toc3 = strip_bookmarks(copy.deepcopy(toc3)) if toc3 is not None else None
for p in entries: content.remove(p)
end_p = content.findall(w("p"))[-1]

all_finding_heads = {id(h) for hs in finding_heads.values() for h in hs}
max_id = max([int(b.get(w("id"))) for b in doc.iter(w("bookmarkStart"))] + [0])
toc_items = []   # (heading text, bookmark name, level)
seen_toc = False
for c in body:
    if c is toc_sdt: seen_toc = True; continue
    if not seen_toc or c.tag != w("p"): continue
    if style(c) == "Heading1" or id(c) in all_finding_heads:
        label = " ".join(text(c).split())
        if not label: continue
        max_id += 1
        name = f"_Toc9{max_id:08d}"
        bs = etree.Element(w("bookmarkStart")); bs.set(w("id"), str(max_id)); bs.set(w("name"), name)
        be = etree.Element(w("bookmarkEnd")); be.set(w("id"), str(max_id))
        pr = c.find(w("pPr"))
        (pr.addnext(bs) if pr is not None else c.insert(0, bs)); c.append(be)
        toc_items.append((label, name, 3 if id(c) in all_finding_heads else 1))

toc_paras = []
for i, (label, name, lvl) in enumerate(toc_items):
    p = copy.deepcopy(toc3 if lvl == 3 else toc1)
    hl = p.find(w("hyperlink")); hl.set(w("anchor"), name)
    seq = [e for e in hl.iter(w("t"), w("fldChar"))]
    first_fld = next(i for i, e in enumerate(seq) if e.tag == w("fldChar"))
    label_ts = [e for e in seq[:first_fld] if e.tag == w("t")]
    label_ts[0].text = label
    for extra in label_ts[1:]: extra.text = ""
    for it_ in p.iter(w("instrText")): it_.text = f" PAGEREF {name} \\h "
    num_t = [e for e in seq[first_fld:] if e.tag == w("t")][-1]; num_t.text = "0"
    if i == 0:
        for r in field_begin: hl.addprevious(copy.deepcopy(r))
    end_p.addprevious(p); toc_paras.append((p, num_t, label))

def mark_toc_dirty():
    # tells Word the Table of Contents is stale, so Word rebuilds it (with correct page numbers) on open
    for fc in toc_sdt.iter(w("fldChar")):
        if fc.get(w("fldCharType")) == "begin":
            fc.set(w("dirty"), "true"); break

def write_docx(path, update_fields):
    out = dict(files)
    for n, root in parts.items():
        out[n] = etree.tostring(root, xml_declaration=True, encoding="UTF-8", standalone=True)
    st = etree.fromstring(files["word/settings.xml"])
    if update_fields and st.find(w("updateFields")) is None:
        u = etree.Element(w("updateFields")); u.set(w("val"), "true")
        after = ["hdrShapeDefaults", "footnotePr", "endnotePr", "compat", "docVars", "rsids"]
        nxt = next((c for c in st if etree.QName(c).localname in after), None)
        nxt.addprevious(u) if nxt is not None else st.append(u)
    out["word/settings.xml"] = etree.tostring(st, xml_declaration=True, encoding="UTF-8", standalone=True)
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as z:
        for n in zin.namelist():
            z.writestr(zin.getinfo(n), out[n])

# Page numbers: the front pages never move, so they are laid out from the known report structure.
ROWS_FIRST_PAGE, ROWS_NEXT_PAGE, LINES_PER_PAGE, CHARS_PER_LINE = 21, 30, 44, 95

def table_pages(rows):
    rows = max(1, rows)
    return 1 if rows <= ROWS_FIRST_PAGE else 1 + -(-(rows - ROWS_FIRST_PAGE) // ROWS_NEXT_PAGE)

def finding_pages(f):
    lines = 14   # severity label, title, section headings, status line and spacing
    for raw in (f["desc"], f["sol"]):
        for _, v in body_paras(raw):
            lines += -(-len(v) // CHARS_PER_LINE) + 1
    if f.get("assets_text"): lines += 2
    for h, ports in f["hosts"].items():
        lines += -(-(len(h) + 2 + len(", ".join(ports))) // CHARS_PER_LINE)
    return max(1, -(-lines // LINES_PER_PAGE))

def page_plan():
    pg = {"CONFIDENTIALITY": 2, "DISCLAIMER": 2, "EXECUTIVE SUMMARY": 3, "SCAN SCOPE": 4, "ASSESSMENT SCOPE": 4,
          "FINDINGS BY CRITICALITY": 5}
    ids = {}
    if RTYPE == "scan":
        rows = sum(max(1, len(sc["findings"])) for sc in scans.values())
        nxt = 5 + table_pages(rows)
        pg["PLUS/DELTA"] = nxt; nxt += 1
    else:
        nxt = 5 + sum(table_pages(len(sc["findings"])) for sc in scans.values())
        for pref in ("EVA", "IVA"):
            if pref not in scans: continue
            pg["DETAILED FINDINGS " + ("EXTERNAL" if pref == "EVA" else "INTERNAL")] = nxt
            if not scans[pref]["findings"]: nxt += 1
            for f in scans[pref]["findings"]:
                ids[f["id"]] = nxt; nxt += finding_pages(f)
    pg["CONCLUSION"] = nxt
    pg["APPENDIX A"] = nxt + 1
    pg["RISK FACTORS"] = nxt + 1
    pg["APPENDIX B"] = nxt + 2
    return pg, ids

def compute_pages():
    pg, ids = page_plan()
    last = 1
    for p, num_t, label in toc_paras:
        m = re.match(r"(EVA|IVA)-\d+", label)
        if m and m.group(0) in ids:
            last = ids[m.group(0)]
        else:
            key = label.upper().replace("\u2013", "").replace("-", "")
            key = " ".join(key.split())
            for k, v in pg.items():
                if k in key: last = v; break
        num_t.text = str(last)
    return True

pages_ok = compute_pages()

out = E["OUT"]
if not out:
    first = next(iter(INPUTS.values()))
    kind = "" if len(scans) == 2 else (" External" if "EVA" in scans else " Internal")
    ref = scan_ref
    if RTYPE == "scan":
        safe = re.sub(r"[^A-Za-z0-9]+", "_", FULL).strip("_")
        name = f"Abacode_{safe}_Executive_Summary_Report_Q{(ref.month - 1)//3 + 1}_{ref.year}.docx"
    else:
        name = f"{ABBR}{kind} EIVA {ref.year} Q{(ref.month - 1)//3 + 1}.docx"
    out = os.path.join(os.path.dirname(os.path.abspath(first)), name)
write_docx(out, update_fields=False)

for pref, sc in scans.items():
    c = sc["counts"]
    print(f"[+] {'External' if pref == 'EVA' else 'Internal'}: {len(sc['findings'])} findings  "
          + "  ".join(f"{s[:4]}:{c[s]}" for s in SEVS))
print(f"[+] Report written to: {out}")
PYEOF
exit 0
